,"sku":"TN-210","category":"office-consumables-toner","before":{"http":"//global.pantum.com/els/wp-content/uploads/2017/07/72fa5570.mov","https":"//youtu.be/vLfJUMNviLY","Тип пристрою":"БФП","2тонера + 2чіпа) http":"//global.pantum.com/els/wp-content/uploads/2017/07/72fa5570.mov https://youtu.be/sRktmwrQSuE https://youtu.be/vLfJUMNviLY"},"after":{"https":"//youtu.be/vLfJUMNviLY","Тип пристрою":"БФП","2тонера + 2чіпа) http":"//global.pantum.com/els/wp-content/uploads/2017/07/72fa5570.mov https://youtu.be/sRktmwrQSuE https://youtu.be/vLfJUMNviLY","Документ постачальника":"http://global.pantum.com/els/wp-content/uploads/2017/07/72fa5570.mov"}},{"id":5812,"sku":"TN-210P","category":"office-consumables-toner","before":{"https":"//youtu.be/vLfJUMNviLY","Тип пристрою":"БФП","2тонера + 2чіпа) Відеогайд по заправці картриджів":"https://youtu.be/sRktmwrQSuE https://youtu.be/vLfJUMNviLY"},"after":{"Тип пристрою":"БФП","2тонера + 2чіпа) Відеогайд по заправці картриджів":"https://youtu.be/sRktmwrQSuE https://youtu.be/vLfJUMNviLY","Документ постачальника":"https://youtu.be/vLfJUMNviLY"}}]$catalog_payload$::jsonb;
 item jsonb; original_row jsonb; after_row jsonb;
BEGIN
 IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid='technoroom_maintenance.product_repair_backup'::regclass) THEN
   RAISE EXCEPTION 'Protected backup table required';
 END IF;
 IF EXISTS(SELECT 1 FROM technoroom_maintenance.product_repair_backup WHERE operation='catalog-spec-mechanical-20261024') THEN
   RAISE EXCEPTION 'Operation already has backups: verify before retry';
 END IF;
 PERFORM id FROM public.products WHERE id IN (SELECT (value->>'id')::bigint FROM jsonb_array_elements(payload)) ORDER BY id FOR UPDATE;
 FOR item IN SELECT value FROM jsonb_array_elements(payload) LOOP
   SELECT to_jsonb(p) INTO original_row FROM public.products p WHERE p.id=(item->>'id')::bigint;
   IF original_row IS NULL OR original_row->>'sku' IS DISTINCT FROM item->>'sku'
      OR original_row->>'category' IS DISTINCT FROM item->>'category'
      OR original_row->'is_active' IS DISTINCT FROM 'true'::jsonb
      OR original_row->'specifications' IS DISTINCT FROM item->'before' THEN
     RAISE EXCEPTION 'Snapshot changed for %: rollback all',item->>'id';
   END IF;
   INSERT INTO technoroom_maintenance.product_repair_backup(operation,product_id,before_row,backed_up_at)
     VALUES('catalog-spec-mechanical-20261024',(item->>'id')::bigint,original_row,now());
   UPDATE public.products SET specifications=item->'after' WHERE id=(item->>'id')::bigint;
   SELECT to_jsonb(p) INTO after_row FROM public.products p WHERE p.id=(item->>'id')::bigint;
   IF after_row->'specifications' IS DISTINCT FROM item->'after'
      OR (after_row-ARRAY['specifications','updated_at']) IS DISTINCT FROM (original_row-ARRAY['specifications','updated_at']) THEN
     RAISE EXCEPTION 'Unexpected fields changed for %: rollback all',item->>'id';
   END IF;
 END LOOP;
END $repair$;
COMMIT;
